import{c as n,$ as i,Q as o,j as s,g as t,o as r,n as l,m as d}from"./chunks/framework.Ce_49mA8.js";const k=JSON.parse('{"title":"Modules Marketplace","description":"Practical guide to the OmniCraft ERP extensions catalog, activating free and premium modules, lazy loading architecture, and database isolation.","frontmatter":{"title":"Modules Marketplace","description":"Practical guide to the OmniCraft ERP extensions catalog, activating free and premium modules, lazy loading architecture, and database isolation.","datePublished":"2026-10-28","dateModified":"2026-11-19","order":21},"headers":[],"relativePath":"docs/spaces/marketplace.md","filePath":"docs/spaces/marketplace.md","lastUpdated":1795046400000}'),c={name:"docs/spaces/marketplace.md"},u={id:"modules-marketplace-specialized-extensions-ecosystem",tabindex:"-1"};function h(p,e,g,m,y,f){const a=i("DocIcon");return o(),s("div",null,[t("h1",u,[r(a,{name:"marketplace"}),e[0]||(e[0]=l(" Modules Marketplace: Specialized Extensions Ecosystem ",-1)),e[1]||(e[1]=t("a",{class:"header-anchor",href:"#modules-marketplace-specialized-extensions-ecosystem","aria-label":'Permalink to "Modules Marketplace: Specialized Extensions Ecosystem"'},"​",-1))]),e[2]||(e[2]=d('<p>The daily craft of an artisan, service technician, or bespoke studio owner is far too nuanced to force into a single, cluttered monolith screen. A specialized tool essential to a leatherworker (such as surface area estimation or stitch pricking calculators) is useless overhead to a watchmaker or electronics technician, unnecessarily crowding the interface and slowing workflow execution.</p><p>To resolve this challenge, OmniCraft ERP employs a modular architecture featuring <strong>cross-cutting modules and an integrated extensions catalog (Marketplace)</strong>:</p><ul><li><strong>Lightweight Core Engine:</strong> the foundation of the platform contains strictly universal business modules (assets, inventory, cash flow, balance sheet, retail sales, and online storefront);</li><li><strong>Tailored Specialization:</strong> craftsmen independently choose and activate niche industry extensions designed specifically for their trade;</li><li><strong>Cross-Cutting Availability:</strong> unlike workshop stockrooms or recipes bound to a single business, active extensions operate globally across all workspaces and preserve their records through organizational changes.</li></ul><hr><h2 id="marketplace-architecture-how-the-catalog-operates" tabindex="-1">Marketplace Architecture: How the Catalog Operates <a class="header-anchor" href="#marketplace-architecture-how-the-catalog-operates" aria-label="Permalink to &quot;Marketplace Architecture: How the Catalog Operates&quot;">​</a></h2><p>Access the catalog directly: select <strong>&quot;Modules Marketplace&quot;</strong> from the right side navigation panel or the application drawer.</p><p>The program displays a modular dialog window populated with available extensions, fetching the active catalog structure via a secure communications channel:</p><div class="craft-window-frame" data-title="Modules Marketplace"><div style="padding:1rem 1.25rem;"><table class="craft-matrix-table" style="margin:0;"><thead><tr><th style="width:45%;">Extension Module</th><th style="width:35%;">Functional Capabilities</th><th style="width:20%;">Status</th></tr></thead><tbody><tr><td><strong>&quot;Ambassador&quot; Module</strong></td><td>Marketing workflows, referral links, digital receipt QR codes, and campaign analytics.</td><td><span style="color:#10b981;font-weight:600;">● Installed</span></td></tr><tr><td><strong>CAD Drafting &amp; Patterns</strong></td><td>Sheet material nesting, cutting allowances, and technical blueprint libraries.</td><td><span style="opacity:0.85;">$39.00</span></td></tr><tr><td><strong>Shipping Carrier Integrations</strong></td><td>Automated label generation, live postage rates, and background tracking updates.</td><td><span style="opacity:0.85;">$25.00</span></td></tr></tbody></table></div></div><h3 id="fault-tolerance-and-offline-stability" tabindex="-1">Fault Tolerance and Offline Stability <a class="header-anchor" href="#fault-tolerance-and-offline-stability" aria-label="Permalink to &quot;Fault Tolerance and Offline Stability&quot;">​</a></h3><p>OmniCraft ERP is built on an uncompromising local-first design principle: network hiccups never halt the master&#39;s workflow:</p><ul><li><strong>In-Memory Catalog Caching:</strong> a fetched catalog is safely cached in application RAM. If internet connectivity drops, the system renders the cached directory instantly without freezing;</li><li><strong>Helpful Network Recovery Screen:</strong> if connection timeouts occur on a fresh cold launch, the dialog displays an informative notification with a network status badge and a <strong>&quot;Retry&quot;</strong> button.</li></ul><hr><h2 id="module-statuses-and-activation-workflows" tabindex="-1">Module Statuses and Activation Workflows <a class="header-anchor" href="#module-statuses-and-activation-workflows" aria-label="Permalink to &quot;Module Statuses and Activation Workflows&quot;">​</a></h2><p>Depending on your active commercial license and module configuration, the action button displays one of four distinct states:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Button State</th><th style="text-align:center;">Interface Icon</th><th style="text-align:left;">Trigger Conditions</th><th style="text-align:left;">Action Executed on Click</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>&quot;Connect Free&quot;</strong></td><td style="text-align:center;">Download</td><td style="text-align:left;">The module is a complimentary system extension (e.g., <em>&quot;Ambassador&quot;</em>).</td><td style="text-align:left;">Immediately binds the module to your license token and surfaces it in the sidebar without downloading files.</td></tr><tr><td style="text-align:left;"><strong>&quot;Buy for $X&quot;</strong></td><td style="text-align:center;">Shopping Cart</td><td style="text-align:left;">A premium, specialized trade extension with a one-time perpetual license.</td><td style="text-align:left;">Launches a secure checkout portal in your default browser. Once confirmed, activation completes automatically.</td></tr><tr><td style="text-align:left;"><strong>&quot;Installed&quot;</strong></td><td style="text-align:center;">Check Circle</td><td style="text-align:left;">The module is already tied to your license key or a Developer PRO+ license is active.</td><td style="text-align:left;">Button is disabled. The extension is ready for immediate production use in the &quot;Extensions&quot; sidebar section.</td></tr><tr><td style="text-align:left;"><strong>&quot;Requires License&quot;</strong></td><td style="text-align:center;">Lock</td><td style="text-align:left;">The software is running under the Free Evaluation tier (20-receipt trial).</td><td style="text-align:left;">Button is locked. Informs the user that modular extensions require a commercial Standard or PRO license.</td></tr></tbody></table><h3 id="step-by-step-guide-connecting-a-free-module" tabindex="-1">Step-by-Step Guide: Connecting a Free Module <a class="header-anchor" href="#step-by-step-guide-connecting-a-free-module" aria-label="Permalink to &quot;Step-by-Step Guide: Connecting a Free Module&quot;">​</a></h3><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg></span><span><strong>Step 1: Open the Marketplace.</strong> Click <strong>&quot;Modules Marketplace&quot;</strong> in the side navigation panel or application drawer.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg></span><span><strong>Step 2: Select Your Tool.</strong> Locate the module card (such as &quot;Ambassador&quot;) and click the emerald <strong>&quot;Connect Free&quot;</strong> button.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14"></path><path d="m12 5 7 7-7 7"></path></svg></span><span><strong>Step 3: Instant Readiness.</strong> The system verifies the cryptographic license token and mounts the new module into your sidebar menu. No application restart or external downloads required.</span></li></ul><h3 id="purchasing-commercial-trade-modules" tabindex="-1">Purchasing Commercial Trade Modules <a class="header-anchor" href="#purchasing-commercial-trade-modules" aria-label="Permalink to &quot;Purchasing Commercial Trade Modules&quot;">​</a></h3><p>OmniCraft ERP rejects predatory recurring microtransactions. Commercial modules are acquired on a <strong>one-time, perpetual basis</strong>:</p><ol><li>Click <strong>&quot;Buy for $X&quot;</strong> on your chosen trade extension card;</li><li>Your default web browser opens the verified checkout portal;</li><li>Complete the payment via credit card, wire transfer, or instant payment methods;</li><li>The billing server binds the module ID to your personal license key. Upon returning to OmniCraft ERP, the module transitions to <strong>&quot;Installed&quot;</strong>.</li></ol><div class="tip custom-block"><p class="custom-block-title">Fair Economics for Craftsmen</p><p>You never pay for features you do not use. A carpentry shop invests in sheet nesting, an apparel brand in sizing charts, and a hardware repair center in vendor parts catalogs. The core ERP remains lean and completely free of artificial bloat.</p></div><hr><h2 id="engineering-standards-monolithic-security-and-lazy-loading" tabindex="-1">Engineering Standards: Monolithic Security and Lazy Loading <a class="header-anchor" href="#engineering-standards-monolithic-security-and-lazy-loading" aria-label="Permalink to &quot;Engineering Standards: Monolithic Security and Lazy Loading&quot;">​</a></h2><p>Most software systems offering add-on marketplaces suffer from two chronic architectural flaws: malware vulnerabilities when downloading unverified external code, and performance degradation caused by memory leaks.</p><p>OmniCraft ERP eliminates these risks at the binary compilation layer:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"></span><div><strong>Core ERP Framework:</strong><br> Assets, Warehouse, Cash, Balance — compiled directly into the binary and immediately operational. </div></li><li><span class="craft-list-bullet"></span><div><strong>Built-In &quot;Ambassador&quot; Module:</strong><br> Compiled within the monolithic executable; loaded into RAM strictly when the tab is accessed (0 MB idle). </div></li><li><span class="craft-list-bullet"></span><div><strong>Future Industry Extensions:</strong><br> Isolated architectural capsules lazily initialized on demand without external file downloads. </div></li></ul><h3 id="_1-in-tree-monolithic-compilation" tabindex="-1">1. In-Tree Monolithic Compilation <a class="header-anchor" href="#_1-in-tree-monolithic-compilation" aria-label="Permalink to &quot;1. In-Tree Monolithic Compilation&quot;">​</a></h3><p>All official extensions within the OmniCraft ERP ecosystem are compiled directly into the monolithic binary executable using industrial C-level translation.</p><ul><li><strong>No Dynamic File Downloads:</strong> Clicking &quot;Connect&quot; never downloads dynamic libraries (<code>.dll</code>) or raw scripts (<code>.py</code>) from external web servers. The code is already present, encrypted, and cryptographically verified within the binary;</li><li><strong>100% Protection Against Vulnerabilities:</strong> Third-party remote code execution (RCE) vectors through plugin tampering are architecturally impossible;</li><li><strong>Zero Antivirus Conflicts:</strong> Windows Defender and enterprise endpoint scanners never generate false-positive alerts, as file disk structures remain unmodified.</li></ul><h3 id="_2-lazy-loading-zero-idle-memory-overhead" tabindex="-1">2. Lazy Loading: Zero Idle Memory Overhead <a class="header-anchor" href="#_2-lazy-loading-zero-idle-memory-overhead" aria-label="Permalink to &quot;2. Lazy Loading: Zero Idle Memory Overhead&quot;">​</a></h3><p>Every module operates as an isolated architectural capsule.</p><p>Until the craftsman clicks the module tab in the side menu, its interface elements, event handlers, and SQLite query bridges <strong>are never initialized in computer RAM</strong>. Having five or twenty modules active inside the binary does not add a single millisecond to application boot times.</p><div class="info custom-block"><p class="custom-block-title">Engineering Note: How Lazy Loading Preserves Performance</p><p>During startup, OmniCraft ERP parses only lightweight declarative module manifests (IDs, titles, and icons). Database migrations and UI controls instantiate strictly on-demand upon first user interaction.</p></div><hr><h2 id="data-isolation-global-extensions-vs-local-workspaces" tabindex="-1">Data Isolation: Global Extensions vs. Local Workspaces <a class="header-anchor" href="#data-isolation-global-extensions-vs-local-workspaces" aria-label="Permalink to &quot;Data Isolation: Global Extensions vs. Local Workspaces&quot;">​</a></h2><p>The OmniCraft ERP modular engine strictly separates data boundaries:</p><table class="craft-matrix-table"><thead><tr><th style="width:35%;">Database File</th><th style="width:25%;">Scope Layer</th><th style="width:40%;">Stored Domain Data</th></tr></thead><tbody><tr><td><code>global_extensions.db</code></td><td><strong>Global Layer</strong></td><td>Marketing, referral linkages, campaigns, and cross-workspace attribution.</td></tr><tr><td><code>workspace.db</code></td><td><strong>Local Workspace</strong></td><td>Warehouse stocks, machinery, cash flow, and client orders of a specific shop.</td></tr></tbody></table><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><line x1="12" x2="12" y1="15" y2="3"></line><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"></path></svg></span><span><strong>Cross-Cutting Global Modules:</strong> Extensions like &quot;Ambassador&quot; maintain their schema inside a dedicated database: <code>global_extensions.db</code>. They operate above individual workshops.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path><polyline points="7 10 12 15 17 10"></polyline><line x1="12" x2="12" y1="15" y2="3"></line></svg></span><span><strong>Immunity to Workspace Resets:</strong> If you reset, archive, or purge a specific craft workspace, global modules retain 100% of their records. Referral networks, campaign histories, and marketing links remain intact.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><rect width="18" height="18" x="3" y="3" rx="2"></rect><path d="M3 9h18"></path><path d="M9 21V9"></path></svg></span><span><strong>Workspace-Bound Extensions:</strong> Modules dealing directly with shop-floor operations (material nesting, bespoke service jobs) write tables into the active workspace database using the <code>mod_*</code> prefix.</span></li></ul><div class="tip custom-block"><p class="custom-block-title">Partnership Continuity Across Businesses</p><p>You can run a leather goods atelier, simultaneously manage a tool sharpening shop, and close an underperforming retail project. The &quot;Ambassador&quot; module continues tracking commissions and partner traffic seamlessly regardless of business closures.</p></div><hr><h2 id="licensing-tiers-and-module-availability" tabindex="-1">Licensing Tiers and Module Availability <a class="header-anchor" href="#licensing-tiers-and-module-availability" aria-label="Permalink to &quot;Licensing Tiers and Module Availability&quot;">​</a></h2><p>Modular access is aligned with your active commercial license level:</p><table tabindex="0"><thead><tr><th style="text-align:left;">License Tier</th><th style="text-align:center;">Marketplace Access</th><th style="text-align:center;">Free Modules</th><th style="text-align:center;">Premium Module Add-ons</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Free Evaluation (Trial)</strong></td><td style="text-align:center;">Browse Catalog Only</td><td style="text-align:center;">Locked (Requires License)</td><td style="text-align:center;">Locked (Requires License)</td></tr><tr><td style="text-align:left;"><strong>Standard License</strong></td><td style="text-align:center;">Full Access</td><td style="text-align:center;">1-Click Activation</td><td style="text-align:center;">One-Time Purchase Available</td></tr><tr><td style="text-align:left;"><strong>PRO License</strong></td><td style="text-align:center;">Full Access</td><td style="text-align:center;">1-Click Activation</td><td style="text-align:center;">One-Time Purchase Available</td></tr><tr><td style="text-align:left;"><strong>PRO+ (Developer License)</strong></td><td style="text-align:center;">Full Access</td><td style="text-align:center;">Pre-Activated</td><td style="text-align:center;">All Extensions Unlocked</td></tr></tbody></table><hr><h2 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h2><h3 id="is-an-active-internet-connection-required-to-use-an-installed-module" tabindex="-1">Is an active internet connection required to use an installed module? <a class="header-anchor" href="#is-an-active-internet-connection-required-to-use-an-installed-module" aria-label="Permalink to &quot;Is an active internet connection required to use an installed module?&quot;">​</a></h3><p>No. An internet connection is required for only a few seconds during initial activation or purchase to verify the cryptographic license signature. All routine operations (creating campaigns, generating links, running calculations) execute <strong>100% locally and offline</strong>.</p><h3 id="what-happens-to-activated-modules-when-migrating-to-a-new-computer" tabindex="-1">What happens to activated modules when migrating to a new computer? <a class="header-anchor" href="#what-happens-to-activated-modules-when-migrating-to-a-new-computer" aria-label="Permalink to &quot;What happens to activated modules when migrating to a new computer?&quot;">​</a></h3><p>All module authorizations are cryptographically anchored to your personal license key. When setting up OmniCraft ERP on a new computer, enter your key in Program Settings: all previously acquired extensions unlock automatically.</p><h3 id="can-an-unused-module-be-hidden-from-the-sidebar-menu" tabindex="-1">Can an unused module be hidden from the sidebar menu? <a class="header-anchor" href="#can-an-unused-module-be-hidden-from-the-sidebar-menu" aria-label="Permalink to &quot;Can an unused module be hidden from the sidebar menu?&quot;">​</a></h3><p>Yes. You can toggle sidebar menu visibility in workspace settings to keep your interface clean and focused without deleting underlying module database tables.</p>',51))])}const v=n(c,[["render",h]]);export{k as __pageData,v as default};
